APP_PATH = "frontend/src/App.tsx"
DEBT_CARD = "frontend/src/components/DashboardVehicleStateCard.tsx"
FINAL_IMPORT = 'import "./styles/cut-approved-themes.css";'
OLD_DECORATIVE = (
    'import "./styles/cut-design-final-touches.css";',
    'import "./styles/cut-approved-stripes-v3.css";',
)
EXPECTED_UNFIXED_DEBT_HASH = "68077af0b550e96b656704fc8ca8321140ab750f08e5a7a42808245ceca23c75"


def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True,exist_ok=True)
    fd, temp = tempfile.mkstemp(prefix=".cut-approved-theme-",suffix=".tmp",dir=path.parent)
    try:
        with os.fdopen(fd,"wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temp,path)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)


def updated_app_data(original: bytes) -> bytes:
    try:
        text=original.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise RuntimeError("App.tsx is not UTF-8; nothing changed") from exc
    if not all(x in text for x in (
        'className="app-shell cut-modern-app"',
        'className="cut-masthead"',
        'className="cut-welcome-banner"',
        'import "./styles/cut-dashboard-layout.css";',
    )):
        raise RuntimeError("Approved React layout not recognized: no files changed")
    newline="\r\n" if "\r\n" in text else "\n"
    # Remove ONLY known obsolete additive CSS imports; do not alter business code.
    for deprecated in OLD_DECORATIVE:
        text=re.sub(r"(?m)^" + re.escape(deprecated) + r"[ \t]*(?:\r?\n)?", "", text)
    if FINAL_IMPORT not in text:
        matches=list(re.finditer(r'^import "\./styles/[A-Za-z0-9_-]+\.css";[ \t]*(?:\r?\n|$)', text, re.MULTILINE))
        if not matches:
            raise RuntimeError("No known CSS import anchor in App.tsx; no files changed")
        end=matches[-1].end()
        text=text[:end]+FINAL_IMPORT+newline+text[end:]
    if text.count(FINAL_IMPORT)!=1:
        raise RuntimeError("Duplicate approved CSS imports: no files changed")
    bom=b"\xef\xbb\xbf" if original.startswith(b"\xef\xbb\xbf") else b""
    return bom+text.encode("utf-8")


def fix_debt_if_stock(original: bytes) -> bytes | None:
    # Older known version directly calls formatMoney(debt.debt), showing undefined.
    # Do not overwrite customer-specific edits or valid custom formatting.
    if sha(original)!=EXPECTED_UNFIXED_DEBT_HASH:
        return None
    text=original.decode("utf-8-sig")
    needle='''{formatMoney(
                          debt.debt,
                        )}'''
    replacement='''{(() => {
                          const raw = debt.debt;
                          if (raw == null || String(raw).trim() === "") {
                            return "Сумма не указана";
                          }
                          const numeric = Number(String(raw).trim().replace(/\\s/g, "").replace(",", "."));
                          return Number.isFinite(numeric)
                            ? formatMoney(numeric.toFixed(2))
                            : "Сумма не указана";
                        })()}'''
    if text.count(needle)!=1:
        raise RuntimeError("Unexpected debt card format: nothing changed")
    return text.replace(needle,replacement).encode("utf-8")


def main() -> int:
    print("=== CUT Improvement Auto / APPROVED DARK + LIGHT / 06.11.2026 ===")
    script=Path(__file__).resolve()
    root=script.parent.parent
    if (script.parent.name.lower()!="scripts"
        or not (root/"backend/app/main.py").is_file()
        or not (root/APP_PATH).is_file()):
        raise RuntimeError("Put this installer in the real PROJECT/scripts directory")
    prerequisites=("frontend/src/styles/app.css",
                   "frontend/src/styles/cut-night-drive.css",
                   "frontend/src/styles/cut-light-drive.css",
                   "frontend/src/styles/cut-dashboard-layout.css",
                   "frontend/src/components/CutThemeControl.tsx",
                   "frontend/public/cut-night-assets/improvement-auto-logo.png")
    for rel in prerequisites:
        if not (root/rel).is_file():
            raise RuntimeError("Prerequisite missing: "+rel+"; no changes made")

    # Decode and verify EVERYTHING, including image assets, before touching files.
    changes={}
    for rel, record in RESOURCES.items():
        expected, packed=record
        data=zlib.decompress(base64.b64decode(packed))
        if sha(data)!=expected:
            raise RuntimeError("Embedded SHA-256 verification failed: "+rel)
        target=root/rel
        if target.is_symlink():
            raise RuntimeError("Symlink resource refused: "+rel)
        if target.is_file():
            if sha(target.read_bytes())!=expected:
                raise RuntimeError("Custom design resource exists; refusing to overwrite: "+rel)
        else:
            changes[target]=data

    app=root/APP_PATH
    if app.is_symlink():
        raise RuntimeError("Symlink App.tsx refused; no changes made")
    old=app.read_bytes()
    new=updated_app_data(old)
    if new!=old:
        changes[app]=new

    card=root/DEBT_CARD
    if card.is_file() and not card.is_symlink():
        newcard=fix_debt_if_stock(card.read_bytes())
        if newcard is not None and newcard!=card.read_bytes():
            changes[card]=newcard

    if not changes:
        print("OK: This approved design is already installed; nothing changed")
        return 0

    # Archive only the exact original files we are about to change.
    stamp=datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    archive=root.parent/"CUT_Improvement_Auto_DevArchive"/"approved_themes_20261106_backups"/stamp
    archive.mkdir(parents=True,exist_ok=False)
    original={}
    for target in changes:
        old_data=target.read_bytes() if target.is_file() else None
        original[target]=old_data
        if old_data is not None:
            dest=archive/target.relative_to(root)
            dest.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(target,dest)
            if sha(dest.read_bytes())!=sha(old_data):
                raise RuntimeError("Backup verification failed; no files changed")

    # Install images/CSS before importing CSS from React. Roll back all writes on error.
    installed=[]
    try:
        for target in sorted(changes,key=lambda p:(p==app,str(p))):
            atomic_write(target,changes[target])
            installed.append(target)
            if sha(target.read_bytes())!=sha(changes[target]):
                raise RuntimeError("Post-install file hash mismatch: "+str(target))
    except BaseException:
        for target in reversed(installed):
            previous=original[target]
            if previous is None:
                target.unlink(missing_ok=True)
            else:
                atomic_write(target,previous)
        print("ERROR: All written changes reverted. Backup: "+str(archive),file=sys.stderr)
        raise

    print("OK: one brand logo in the masthead; no duplicate logo in the sidebar")
    print("OK: dark theme matches approved Navy + Gold concept")
    print("OK: light theme uses white/grey surfaces, same block dimensions")
    print("OK: each theme uses ONE approved automotive image")
    print("OK: previous decorative stripes/imports disabled; files preserved")
    print("OK: existing real data, theme preference and navigation retained")
    print("BACKUP: "+str(archive))
    print("CHANGED: "+", ".join(str(p.relative_to(root)) for p in installed))
    print("UNTOUCHED: frontend/dist, active release 0.1.0, backend, database, MAX, photos, .env, backups, Git")
    print("NEXT: open Vite at http://127.0.0.1:5173/ (NO build or activation yet)")
    return 0

if __name__=="__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print("INSTALL FAILED: "+str(exc),file=sys.stderr)
        raise SystemExit(1)
